module round_robin_arbiter_4 (
    input  wire       clk,
    input  wire       rst_n,
    input  wire [3:0] req,
    output reg  [3:0] grant
);

    reg [1:0] last_grant_ptr;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            grant <= 4'b0000;
            last_grant_ptr <= 2'd0;
        end else begin
            // Simplified priority rotation
            if (req == 4'b0000) begin
                grant <= 4'b0000;
            end else begin
                case (last_grant_ptr)
                    2'd0: begin
                        if (req[1]) grant <= 4'b0010;
                        else if (req[2]) grant <= 4'b0100;
                        else if (req[3]) grant <= 4'b1000;
                        else grant <= 4'b0001;
