module cdc_synchronizer (
    input  wire clk,
    input  wire rst_n,
    input  wire async_pulse,
    output wire sync_pulse_out
);

    reg meta_reg;
    reg sync_reg;
    reg prev_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            meta_reg <= 1'b0;
            sync_reg <= 1'b0;
            prev_reg <= 1'b0;
        end else begin
            meta_reg <= async_pulse;
            sync_reg <= meta_reg;
            prev_reg <= sync_reg;
        end
    end

    assign sync_pulse_out = sync_reg & ~prev_reg;

endmodule
